    export function promisePodaniSablona(that: GContent, kontrolovatRok: boolean, ixsPit: string): JQueryPromise<string> {

        //stejné podaní aji na seznamu dokladů
        var def = $.Deferred();
        var that = that;

        //var that = this
        that.beginOperation("jres:31302224"); //RC 31302224 : Podávám nový doklad

        that.isl.PokDoklad.podaniSablona(rq => {
            return {
                ixsPit: ixsPit,
                kontrolaRok: kontrolovatRok
            }
        })
            .get()
            .then(function (ixp) {
                def.resolve(ixp);
            })
            .fail(function (xhr, type: string, vobj?: ObjectLiteral<any>) {
                if (type === "exception" && vobj) {
                    if (vobj.baseType === "Gordic.General.GHplValidationException") {
                        vobj.handled = true;
                        def.reject(vobj.baseMessage);
                    }
                    else if (vobj.data.member == "kontrolaRok") {
                        vobj.handled = true;
                        return that.dialogs.confirm(vobj.baseMessage + "</ Pokračovat>").createDialogPromise("yes").then(
                            function () {
                                return promisePodaniSablona(that, false, ixsPit)
                                    .then(function (ixp) {

                                        def.resolve(ixp);
                                    })
                                    .fail(function (xhr, type : string, vobj?: ObjectLiteral<any>) {
                                        if (type === "exception" && vobj) {
                                            if (vobj.baseType === "Gordic.General.GHplValidationException") {
                                                vobj.handled = true;
                                                def.reject(vobj.baseMessage);
                                            }
                                            else {

                                                def.reject();
                                            }
                                        }

                                        def.reject();
                                    });
                            }
                        );

                    }
                    else {

                        def.reject();
                    }
                }
                else {

                    def.reject();
                }
            })
            .always(function () {
                that.endOperation()
            });

        return def.promise();
    }


    function sejmutiStitkem(that: any, gingenixp: string): JQueryPromise<string> {
       
        var def = $.Deferred();
        var that = that;

        if (Gordic.Eko.Utils.GetEkoUserSettingsPidSejmuti(that, gingenixp) === "1") { //generování
            Gordic.Wfl.Dialogs.GenerovaniIxpDlg(that, {
                TypDok: Gordic.Wfl.Globals.Enums.TypDok.Vlastni,
                TypId: Gordic.Wfl.Globals.Enums.TypId.IXP,
                DotazPriExistenciVJineAgende: false,
                HlaseniPriExistenciVAgende: false,
                ZpusobGenerovani: Gordic.Wfl.Globals.Enums.ZpusobGenerovaniIxp.Stitkem
            }, Gordic.Global.Enums.ModOtevreni.showModalWindow)!
                .on("close", function (ev,retVal) {
                    if (retVal == "undefined" || retVal == null || retVal.values == "undefined") {

                        def.reject();
                    } else {
                        def.resolve(retVal?.Ixp);
                    }

                });
        }
        else {


            def.resolve("");
        }

        return def.promise();



    }

