    function promisePrebiranePlatby(platba: Gordic.Hpl.Interface.GPokBankPlatbyDto, that : any): JQueryPromise < Gordic.Hpl.Interface.GPokBankPlatbyDto[] > {

        var def = $.Deferred();
        var that = that;

        if(platba.typ_ag == 350) {
        //ISL pro načtení všech přebíraných plateb - ixp_pl_vcetne
        that.isl.PokBankPlatby.list(rq => {
            return {
                filters: {
                    xxx_neplatny_esu: true,
                    ixp_pl_vcetne: platba.ixp
                }
            }
        }).get()
            .then(function (data) {

                if (data.data.length > 0) {

                    let newArray: Gordic.Hpl.Interface.GPokBankPlatbyDto[] = data.data;


                    let index = 0;
                    let indexNew = 0;
                    newArray.forEach(function (x) {
                        if (x.ixp == platba.ixp && x.radek_uhr == platba.radek_uhr) {
                            let test = newArray[indexNew];
                            newArray[indexNew] = x;
                            newArray[index] = test;
                            indexNew++;
                        }
                        index++;
                        if (index == newArray.length)
                            def.resolve(newArray);
                    })



                }
                else {

                    def.resolve(null);
                }

            });
    }
            else {

        def.resolve(null);
    }


    return def.promise();




}

    export function doplneniPlatby(ixpPlatba: string,vsPlatba: string, radekUhrPlatba: number , that: any): JQueryPromise<Gordic.Pok.WebClient.GPokOcekavanePlatbyPomocDto[]> {

        var that = that;
        var def = $.Deferred();
        let napojeniPoplatnici = that.globalSettings!.get("Pok.OcekavanePlatby.Napojene");
        let prebratPoplatniky = that.globalSettings!.get("Pok.OcekavanePlatby.Poplatniky");
        let prevzitSaldo = that.globalSettings!.get("Pok.OcekavanePlatby.Polozka");
        let splatkoveSaldo = that.globalSettings!.get("Pok.OcekavanePlatby.Saldo");
        let datumSaldo = that.globalSettings!.get("Pok.Nastaveni.DatSaldaDdp");
        if (datumSaldo == null)
            datumSaldo = new Date();
        let rezimZakladani = that.pokParams.HplRadRzpOcp;
        let l_aoPoplatniciRows: Hpl.Interface.GPokBankPlatbyDto[];
        let l_oReturnDto: Gordic.Pok.WebClient.GPokOcekavanePlatbyPomocDto[] = [];
        let platba: Hpl.Interface.GPokBankPlatbyDto;


        that.isl.PokBankPlatby.list(rq => {
            return {
                filters: {
                    ixp: ixpPlatba,
                    vs: vsPlatba,
                    radek_uhr: radekUhrPlatba
                },
                fragments: ["*"]
            }
        }).get().then(function (data) {
            platba = data.data[0]; //poresit asi radek_uhr kdyz jsou data zobrazena kumulovane a radek_uhr neni (kdyz vrai více řádků, te beru an tvrdo na pozici 0 a ten rade_uhr ma), jeste proverit
            //ošetřit asi všechny erro na reject??
            if (platba != null) {
                //načtení přebíraných plateb , je potřeba později
                promisePrebiranePlatby(platba, that).then(function (data) {
                    //nastavení načtených dat do objektu pro pozdější použití
                    l_aoPoplatniciRows = data;
                }).then(function () {

                    //pokud nejsou žádné přebírané platby, tak nastavím přebírat platby na false
                    if (l_aoPoplatniciRows == null)
                        prebratPoplatniky = false;
                    if (prevzitSaldo && platba.typ_ag == 350) {
                        if (!prebratPoplatniky) {
                            that.isl.PokBankPlatby.listPripadyDdp(rq => {
                                return {
                                    filters: {
                                        ixp: platba.ixp
                                    },
                                    fragments: ["*"]
                                }
                            }).get().then(function (data) {

                                let row = data.data[0];

                                if (platba.saldo != null) {
                                    row.c_saldo = platba.saldo;
                                    l_oReturnDto.push({ ixs_esu: row.ixs_esu, c_celkem: new Decimal(row.c_saldo), c_celkem_m: Decimal.mul(row.c_saldo, (that.model.kurz_doklad ?? 1)), vs: row.vs, ss: row.ss, ixp_buc: row.ixp });
                                    def.resolve(l_oReturnDto);
                                }
                                else {
                                    //spocitej saldo
                                    //načíst seznam s fragmentem "SALDO"
                                    that.isl.PokBankPlatby.listPripadyDdp(rq => {
                                        return {
                                            filters: {
                                                ixp: platba.ixp,
                                                splatkove_saldo: splatkoveSaldo,
                                                napojene_pripady: napojeniPoplatnici,
                                                dat_do: datumSaldo

                                            },
                                            fragments: ["SALDO", "*"]
                                        }
                                    }).get().then(function (data) {
                                        row.c_saldo = new Decimal(data.data[0].c_saldo ?? 0);
                                        l_oReturnDto.push({ ixs_esu: row.ixs_esu, c_celkem: new Decimal(row.c_saldo), c_celkem_m: Decimal.mul(row.c_saldo!, (that.model.kurz_doklad ?? 1)), vs: row.vs, ss: row.ss, ixp_buc: row.ixp });
                                        def.resolve(l_oReturnDto);
                                    })
                                }
                            });
                        } //end !prebratPoplatniky
                        else { //prebrat poplatniky
                            if (rezimZakladani == 100) //jedna
                            {//prebrat poplatniky - zakladat jako jednu položku
                                that.isl.PokBankPlatby.listPripadyDdp(
                                    {
                                        filters: {
                                            ixp: l_aoPoplatniciRows.map(t => t.ixp).filter((value, index, self) => self.indexOf(value) === index),
                                            splatkove_saldo: splatkoveSaldo,
                                            napojene_pripady: napojeniPoplatnici,
                                            dat_do: datumSaldo
                                        },
                                        fragments: ["SALDO", "*"]

                                    }).get().then(function (data) {
                                        //objekt pro nápočet celkového salda, protože je založene jako jeden řádek, tak potřebuji jeho celou výši
                                        let celkemSaldo: Decimal = new Decimal(0);
                                        let index = 0;
                                        data.data.forEach(function (x) {
                                            index++;
                                            //tady to ješte může jinak počítat
                                            //v původním se volá znova seznam případů za ixp a počítá se z toho saldo
                                            console.log(x);
                                            celkemSaldo = Decimal.add(celkemSaldo, x.c_saldo ?? 0);

                                            if (index === data.data.length) {
                                                l_oReturnDto.push({ ixs_esu: platba.ixs_esu, c_celkem: new Decimal(celkemSaldo), c_celkem_m: Decimal.mul(celkemSaldo!, (that.model.kurz_doklad ?? 1)), vs: platba.vs, ss: platba.ss, ixp_buc: platba.ixp, radek_uhr_buc: platba.radek_uhr });
                                                def.resolve(l_oReturnDto);
                                            }
                                            //ddRowToNahled(row, l_nSum, l_nSum / Kurz);
                                        })//end foreach                                 
                                    })//end listPripadyDdp

                            }
                            else if (rezimZakladani == 200) { //vice
                                that.isl.PokBankPlatby.listPripadyDdp(rq => {
                                    return {
                                        filters: {
                                            ixp: l_aoPoplatniciRows.map(t => t.ixp).filter((value, index, self) => self.indexOf(value) === index),
                                            splatkove_saldo: splatkoveSaldo,
                                            napojene_pripady: napojeniPoplatnici,
                                            dat_do: datumSaldo
                                        },
                                        fragments: ["SALDO", "*"]
                                    }
                                }).get().then(function (data) {
                                    //nějáké řazení, zatím tady není, nevím jestli je potřeba                                      
                                    let index = 0;

                                    data.data.forEach(function (x) {
                                        index++;

                                        //pokud není salo 0, tak předám jako řádek do výsledného objektu
                                        if (!new Decimal(x.c_saldo ?? 0).equals(0)) {
                                            l_oReturnDto.push({ ixs_esu: x.ixs_esu, c_celkem: new Decimal(x.c_saldo ?? 0), c_celkem_m: Decimal.mul(x.c_saldo!, (that.model.kurz_doklad ?? 1)), vs: x.vs, ss: x.ss, ixp_buc: x.ixp });
                                        }
                                        //pokud projdu všechny záznamy
                                        if (index === data.data.length)
                                            def.resolve(l_oReturnDto);
                                    }) //end foreach
                                }) //end listPripadyDDp
                            }//end else !prebratPoplatniky
                        } //end prevzitSaldo && platba.typ_ag == 350
                    } else if (platba.typ_ag == 350) {
                        if (!prebratPoplatniky) {
                            //AddRowToNahled(row);            
                            l_oReturnDto.push({ ixs_esu: platba.ixs_esu, c_celkem: Decimal.sub(platba.c!, platba.c_par!), c_celkem_m: Decimal.sub(platba.c_mena!, platba.c_par_mena!), vs: platba.vs, ss: platba.ss, ixp_buc: platba.ixp, radek_uhr_buc: platba.radek_uhr });
                            def.resolve(l_oReturnDto);

                        }//!prebrat poplatniky
                        else {
                            if (rezimZakladani == 100) //jedna
                            {
                                let index = 0;
                                let castkaCelkem = parseDecimal(0);
                                let castkaCelkemMena = parseDecimal(0);


                                l_aoPoplatniciRows.forEach(function (x) {

                                    index++;
                                    let castka = Decimal.sub(x.c ?? 0, x.c_par ?? 0);
                                    let castkaMena = Decimal.sub(x.c_mena ?? 0, x.c_par_mena ?? 0);

                                    castkaCelkem = Decimal.add(parseDecimal(castkaCelkem), castka);
                                    castkaCelkemMena = Decimal.add(parseDecimal(castkaCelkemMena), castkaMena);

                                    if (index === l_aoPoplatniciRows.length) {
                                        l_oReturnDto.push({ ixs_esu: platba.ixs_esu, c_celkem: castkaCelkem, c_celkem_m: castkaCelkemMena, vs: platba.vs, ss: platba.ss, ixp_buc: platba.ixp, radek_uhr_buc: platba.radek_uhr });
                                        return def.resolve(l_oReturnDto);

                                    }
                                })

                            }//end rezimZakladani == 100
                            else if (rezimZakladani == 200) //vice
                            {
                                //debugger;
                                //profiltrování na požadované záznamy
                                let l_aoPoplatniciRowsFilterArray = l_aoPoplatniciRows.filter(x =>
                                    !(Decimal.sub(x.c_mena ?? 0, x.c_par_mena ?? 0)).equals(parseDecimal(0)) ||
                                    !(Decimal.sub(x.c ?? 0, x.c_par ?? 0)).equals(parseDecimal(0)) ||
                                    (platba.ixp === x.ixp! && platba.radek_uhr === x.radek_uhr!));

                                let index = 0;
                                l_aoPoplatniciRowsFilterArray.forEach(function (x) {
                                    index++;
                                    l_oReturnDto.push({ ixs_esu: x.ixs_esu, c_celkem: Decimal.sub(x.c!, x.c_par!), c_celkem_m: Decimal.sub(x.c_mena!, x.c_par_mena!), vs: x.vs, ss: x.ss, ixp_buc: x.ixp, radek_uhr_buc: x.radek_uhr });
                                    if (index === l_aoPoplatniciRowsFilterArray.length)
                                        def.resolve(l_oReturnDto);

                                })
                            }//end rezimZakladani == 200
                        }//end !prebratPoplatniky
                    }//platby.typ_ag == 350
                    else { //neprevzit saldo ddp a ne ddp - ostatni
                        if (platba != null) {
                            l_oReturnDto.push({ ixs_esu: platba.ixs_esu, c_celkem: Decimal.sub(platba.c!, platba.c_par!), c_celkem_m: Decimal.sub(platba.c_mena!, platba.c_par_mena!), vs: platba.vs, ss: platba.ss, ixp_buc: platba.ixp, radek_uhr_buc: platba.radek_uhr });
                            def.resolve(l_oReturnDto);
                        }
                    }//end prevzitSaldo && platba.typ_ag == 350 /else if platby.typ_ag == 350
                }); //end then function
            }//end platba != null
            else { def.resolve(null); }
            //return def.promise();
        });
        
return def.promise();
    }

   
